sed -i '/text = "JENE can display lyrics embedded in your music files or local .LRC files.",/a \
            Spacer(modifier = Modifier.height(16.dp))\n            val context = LocalContext.current\n            val launcher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->\n                if (uri != null) {\n                    context.contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION)\n                    viewModel.saveLyricUri(song.id, uri.toString())\n                    hasAttemptedLoad = false \/\/ trigger reload\n                }\n            }\n            Button(onClick = { launcher.launch(arrayOf("*/*")) }) {\n                Text("Add Lyrics File")\n            }' app/src/main/java/com/jene/music/ui/screens/NowPlayingScreen.kt
